import os, pty, sys, select, time, errno

def run(cmd, script, timeout=10.0):
    """script: list of (wait_substring_or_None, text_to_send)"""
    pid, fd = pty.fork()
    if pid == 0:
        os.execvp(cmd[0], cmd)
    out = b""
    idx = 0
    start = time.time()
    status = None
    while True:
        if time.time() - start > timeout:
            out += b"\n<<TIMEOUT>>"
            os.kill(pid, 9)
            break
        r, _, _ = select.select([fd], [], [], 0.2)
        if r:
            try:
                chunk = os.read(fd, 4096)
            except OSError:
                chunk = b""
            if not chunk:
                break
            out += chunk
        # send next scripted item when its cue is present
        while idx < len(script):
            cue, text = script[idx]
            if cue is None or cue.encode() in out:
                time.sleep(0.15)
                os.write(fd, text.encode())
                idx += 1
                time.sleep(0.15)
            else:
                break
        # check child
        try:
            wpid, st = os.waitpid(pid, os.WNOHANG)
            if wpid == pid:
                status = st
                # drain
                while True:
                    r, _, _ = select.select([fd], [], [], 0.2)
                    if not r: break
                    try: c = os.read(fd, 4096)
                    except OSError: break
                    if not c: break
                    out += c
                break
        except ChildProcessError:
            break
    if status is None:
        try:
            _, status = os.waitpid(pid, 0)
        except ChildProcessError:
            status = 0
    os.close(fd)
    code = os.waitstatus_to_exitcode(status) if status is not None else -1
    return code, out.decode(errors="replace")

if __name__ == "__main__":
    import json
