/// The arguments handed to `App::run`.
///
/// `formlike` owns the confirmation gate (it accepts `y` as well as `yes`), so
/// a `provision` run that would have to confirm passes the framework's own
/// `--yes` and asks the question itself in [`confirm_gate`].
fn dispatch_args<I>(raw: I) -> Vec<String>
where
    I: IntoIterator<Item = String>,
{
    let mut args: Vec<String> = raw.into_iter().collect();

    // Split the argument list into the command words and everything else, so
    // that `formlike help provision` and a file named `questions` are not
    // mistaken for a provisioning run.
    let mut words: Vec<&str> = Vec::new();
    let mut wants_help = false;
    let mut already_yes = false;
    let mut skip_value = false;
    for arg in args.iter().skip(1) {
        if skip_value {
            skip_value = false;
            continue;
        }
        match arg.as_str() {
            "--answers" | "--output" | "--output-file-path" => skip_value = true,
            "--help" | "-h" => wants_help = true,
            "--yes" => already_yes = true,
            flag if flag.starts_with('-') => {}
            word => words.push(word),
        }
    }

    let provisioning = words.as_slice() == ["provision"];

    if provisioning && !wants_help && !already_yes {
        args.push("--yes".to_string());
